package com.portfolio.cms.controller;
import org.springframework.beans.factory.annotation.Value; import org.springframework.core.io.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.nio.file.*;
@RestController @RequestMapping("/media") public class MediaController { @Value("${app.media-dir}") String mediaDir; @GetMapping("/{name:.+}") public ResponseEntity<Resource> get(@PathVariable String name)throws Exception{Path p=Paths.get(mediaDir).resolve(name).normalize();Path root=Paths.get(mediaDir).toAbsolutePath().normalize();if(!p.toAbsolutePath().startsWith(root))return ResponseEntity.status(403).build();Resource r=new UrlResource(p.toUri());if(!r.exists())return ResponseEntity.notFound().build();return ResponseEntity.ok().contentType(MediaType.parseMediaType(Files.probeContentType(p)!=null?Files.probeContentType(p):MediaType.APPLICATION_OCTET_STREAM_VALUE)).body(r);} }
